import android.content.*;import android.net.Uri;import android.media.*;import org.json.*;import java.io.*;import java.nio.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;

public final class AudioEngine {
 public interface Progress{void update(String phase,double fraction);}
 public static final int RATE=48000;
 static void check(AtomicBoolean stop)throws InterruptedException{if(stop.get()||Thread.currentThread().isInterrupted())throw new InterruptedException("Cancelled");}
 static void little(DataOutputStream d,int value,int bytes)throws IOException{for(int i=0;i<bytes;i++)d.write(value>>(8*i));}
 public static void wavHeader(OutputStream stream,long frames)throws IOException{DataOutputStream d=new DataOutputStream(stream);long bytes=frames*4;if(bytes>0xfffffff0L)throw new IOException("Audio exceeds WAV 4 GiB limit.");d.writeBytes("RIFF");little(d,(int)bytes+36,4);d.writeBytes("WAVEfmt ");little(d,16,4);little(d,1,2);little(d,2,2);little(d,RATE,4);little(d,RATE*4,4);little(d,4,2);little(d,16,2);d.writeBytes("data");little(d,(int)bytes,4);}
 public static File decode(Context context,Uri uri,File destination,AtomicBoolean stop)throws Exception{
  MediaExtractor extractor=new MediaExtractor();MediaCodec codec=null;try{extractor.setDataSource(context,uri,null);int track=-1;MediaFormat format=null;for(int i=0;i<extractor.getTrackCount();i++)if(extractor.getTrackFormat(i).getString(MediaFormat.KEY_MIME).startsWith("audio/")){track=i;format=extractor.getTrackFormat(i);break;}if(track<0)throw new IOException("Selected file has no decodable audio track.");extractor.selectTrack(track);codec=MediaCodec.createDecoderByType(format.getString(MediaFormat.KEY_MIME));codec.configure(format,null,null,0);codec.start();boolean inputEnd=false,outputEnd=false;int rate=format.getInteger(MediaFormat.KEY_SAMPLE_RATE),channels=format.getInteger(MediaFormat.KEY_CHANNEL_COUNT),encoding=AudioFormat.ENCODING_PCM_16BIT;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long sourceFrame=0,outFrame=0;float prevL=0,prevR=0;try(BufferedOutputStream out=new BufferedOutputStream(new FileOutputStream(destination),131072)){while(!outputEnd){check(stop);if(!inputEnd){int ix=codec.dequeueInputBuffer(10000);if(ix>=0){ByteBuffer input=codec.getInputBuffer(ix);int n=extractor.readSampleData(input,0);if(n<0){codec.queueInputBuffer(ix,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inputEnd=true;}else{codec.queueInputBuffer(ix,0,n,extractor.getSampleTime(),0);extractor.advance();}}}int ox=codec.dequeueOutputBuffer(info,10000);if(ox==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){MediaFormat f=codec.getOutputFormat();rate=f.getInteger(MediaFormat.KEY_SAMPLE_RATE);channels=f.getInteger(MediaFormat.KEY_CHANNEL_COUNT);encoding=f.containsKey(MediaFormat.KEY_PCM_ENCODING)?f.getInteger(MediaFormat.KEY_PCM_ENCODING):AudioFormat.ENCODING_PCM_16BIT;}else if(ox>=0){ByteBuffer b=codec.getOutputBuffer(ox).order(ByteOrder.LITTLE_ENDIAN);b.position(info.offset);b.limit(info.offset+info.size);int unit=encoding==AudioFormat.ENCODING_PCM_FLOAT?4:2;while(b.remaining()>=unit*channels){float l=0,r=0;for(int ch=0;ch<channels;ch++){float v=unit==4?b.getFloat():b.getShort()/32768f;if(ch==0)l=v;if(ch==1)r=v;}if(channels==1)r=l;while(outFrame*(double)rate/RATE<=sourceFrame){double position=outFrame*(double)rate/RATE;float blend=sourceFrame==0?1:(float)(position-(sourceFrame-1));write16(out,prevL+(l-prevL)*blend);write16(out,prevR+(r-prevR)*blend);outFrame++;}prevL=l;prevR=r;sourceFrame++;}outputEnd=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(ox,false);}}}if(destination.length()<4)throw new IOException("Audio decoder returned no samples.");return destination;}finally{extractor.release();if(codec!=null){try{codec.stop();}catch(Exception ignored){}codec.release();}}}
 static void write16(OutputStream o,double v)throws IOException{int n=(int)Math.round(Math.max(-1,Math.min(.999969482421875,v))*32768);o.write(n&255);o.write((n>>8)&255);}
 static class PCM implements Closeable{RandomAccessFile f;long frames;final LinkedHashMap<Long,byte[]>cache=new LinkedHashMap<Long,byte[]>(16,.75f,true){protected boolean removeEldestEntry(Map.Entry<Long,byte[]>e){return size()>8;}};PCM(File p)throws IOException{f=new RandomAccessFile(p,"r");frames=f.length()/4;}float get(long frame,int channel)throws IOException{if(frame<0||frame>=frames)return 0;long b=frame/4096;byte[]data=cache.get(b);if(data==null){data=new byte[16384];f.seek(b*16384);f.read(data);cache.put(b,data);}int ix=(int)(frame%4096)*4+channel*2;return (short)((data[ix]&255)|((data[ix+1]&255)<<8))/32768f;}public void close()throws IOException{f.close();cache.clear();}}
 static class FX{long first,seed;String id,path;float[] signal;double gain,cents;}
 static List<FX> effects(ATSModel m)throws Exception{List<FX>list=new ArrayList<>();if(!m.direction.optBoolean("sfx_enabled",true))return list;Random random=new Random(m.seed);long last=-RATE;double master=Math.pow(10,ATSModel.obj(m.audio,"sfx").optDouble("gain_db",0)/20);for(int i=1;i<m.scenes.size();i++){ATSModel.Scene s=m.scenes.get(i);JSONArray cues=s.raw.optJSONArray("sfx");List<JSONObject>items=new ArrayList<>();if(cues!=null)for(int k=0;k<cues.length();k++)if(cues.optJSONObject(k)!=null)items.add(cues.optJSONObject(k));String declared=s.trans.optString("sfx","NONE");if(!declared.equals("NONE")){JSONObject cue=new JSONObject();try{cue.put("id",declared);}catch(Exception ignored){}items.add(cue);}for(JSONObject cue:items){long first=Math.round((s.start+cue.optDouble("offset_ms",0)/1000)*RATE);FX fx=new FX();fx.first=first;fx.path="$.scenes["+i+"].sfx";fx.gain=master*Math.pow(10,cue.optDouble("gain_db",-14)/20);fx.id=cue.optString("id");fx.seed=random.nextLong()+cue.optInt("variant",1)*991L;fx.cents=cue.optDouble("pitch_cents",0);list.add(fx);}}list.sort((a,b)->Long.compare(a.first,b.first));for(FX fx:list){if(fx.first-last<RATE*.35)throw new Exception(fx.path+": cue is within 350 ms of another explicit cue");last=fx.first;}return list;}
 static float[] sound(String id,long seed,double cents){int n=(int)(RATE*(id.contains("RISER")?.70:id.contains("WHOOSH")?.48:id.contains("PAGE")?.62:id.contains("BRUSH")?.5:id.contains("IMPACT")?.55:.22));float[]out=new float[n];Random r=new Random(seed);double phase=0,low=0,pitch=Math.pow(2,cents/1200);for(int i=0;i<n;i++){double t=i/(double)RATE,p=i/(double)n,noise=r.nextDouble()*2-1;low=.94*low+.06*noise;double v;if(id.contains("IMPACT")||id.equals("STAMP_THUD")){phase+=2*Math.PI*(70-35*p)*pitch/RATE;v=(Math.sin(phase)*.65+noise*.12)*Math.exp(-t*13);}else if(id.contains("WHOOSH")||id.contains("SWIPE")||id.equals("RISER_SHORT")){v=(noise-low)*Math.pow(Math.sin(p*Math.PI),2)*.45;}else if(id.contains("PAPER")||id.contains("BRUSH")||id.contains("INK")||id.equals("PAGE_TURN")){v=(noise-low)*Math.sin(p*Math.PI)*.3*(.7+.3*Math.sin(t*70));}else{phase+=2*Math.PI*(id.contains("TYPE")?1100:1800)*pitch/RATE;v=(Math.sin(phase)*.2+noise*.2)*Math.exp(-t*55);}out[i]=(float)(v*Math.min(1,i/120.0));}return out;}
 public static File mix(Context c,Project p,File job,AtomicBoolean stop,Progress progress)throws Exception{ATSModel m=p.model;long frames=Math.round(m.duration*RATE);if(frames*16+(p.music==null?0:Math.round(p.media.duration(p.music)*RATE)*4)>job.getUsableSpace()-32*1024*1024)throw new IOException("Not enough free storage for export audio. Free space and retry.");progress.update("Preparing narration",0);File voice=decode(c,p.narration,new File(job,"voice.pcm"),stop);File music=p.music==null?null:decode(c,p.music,new File(job,"music.pcm"),stop);File floatFile=new File(job,"mix.f32");List<FX>fx=effects(m);List<FX>activeFx=new ArrayList<>();int nextFx=0;double voiceGain=m.direction.optDouble("voice_level",1),musicGain=m.direction.optDouble("music_level",.18),duck=Math.pow(10,m.direction.optDouble("duck_db",-9)/20),envelope=0,peak=0,energy=0;long count=0;Loudness loudness=new Loudness();double[] voicePeaks=new double[120],musicPeaks=new double[120];double[]blockEnergy=new double[(int)Math.ceil(frames/(RATE*.4))];long[]blockCount=new long[blockEnergy.length];try(PCM narration=new PCM(voice);PCM bg=music==null?null:new PCM(music);DataOutputStream out=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(floatFile),131072))){long seam=bg==null?0:Math.min((long)(.8*RATE),Math.max(0,bg.frames/4));long period=bg==null?0:bg.frames-seam;for(long frame=0;frame<frames;frame++){if(frame%4096==0){check(stop);progress.update("Mixing voice, music and SFX",frame/(double)frames);}double l=narration.get(frame,0),r=narration.get(frame,1),activity=Math.max(Math.abs(l),Math.abs(r));double coefficient=activity>envelope?.004:.00008;envelope+=(activity-envelope)*coefficient;double duckGain=1-(1-duck)*Math.max(0,Math.min(1,(envelope-.007)/.04));double musicFade=Math.min(1,frame/(RATE*.5))*Math.min(1,(frames-frame)/(RATE*1.5));while(nextFx<fx.size()&&fx.get(nextFx).first<=frame){FX cue=fx.get(nextFx++);cue.signal=sound(cue.id,cue.seed,cue.cents);activeFx.add(cue);}for(Iterator<FX> it=activeFx.iterator();it.hasNext();){FX cue=it.next();if(frame>=cue.first+cue.signal.length){cue.signal=null;it.remove();}}double mixL=0,mixR=0;int bin=(int)Math.min(119,frame*120/Math.max(1,frames));voicePeaks[bin]=Math.max(voicePeaks[bin],Math.max(Math.abs(l),Math.abs(r))*voiceGain);for(int channel=0;channel<2;channel++){double v=(channel==0?l:r)*voiceGain;if(bg!=null&&period>0){long j=frame%period;double mv=bg.get(j,channel);if(j<seam){double blend=j/(double)seam;mv=mv*Math.sin(blend*Math.PI/2)+bg.get(period+j,channel)*Math.cos(blend*Math.PI/2);}double bv=mv*musicGain*duckGain*musicFade;v+=bv;musicPeaks[bin]=Math.max(musicPeaks[bin],Math.abs(bv));}for(FX f:activeFx){long ix=frame-f.first;if(ix>=0&&ix<f.signal.length)v+=f.signal[(int)ix]*f.gain*(envelope>.03?.45:1);}peak=Math.max(peak,Math.abs(v));energy+=v*v;count++;int bx=(int)(frame/(RATE*.4));blockEnergy[bx]+=v*v;blockCount[bx]++;if(channel==0)mixL=v;else mixR=v;out.writeFloat((float)v);}loudness.add(mixL,mixR);}}try(FileOutputStream summary=new FileOutputStream(new File(job,"waveforms.json"))){JSONObject wave=new JSONObject().put("voice",new JSONArray(voicePeaks)).put("music",new JSONArray(musicPeaks));summary.write(wave.toString().getBytes("UTF-8"));}
  JSONObject master=ATSModel.obj(m.audio,"master");String mode=master.optString("mode","LIMIT_ONLY");double gain=1,ceiling=Math.pow(10,master.optDouble("true_peak_db",-1)/20);if(mode.equals("LOUDNORM")){double gated=0;long gn=0;double absolute=-70;double preliminary=10*Math.log10(Math.max(1e-12,energy/Math.max(1,count)))-.691;for(int i=0;i<blockEnergy.length;i++){double blockLufs=10*Math.log10(Math.max(1e-12,blockEnergy[i]/Math.max(1,blockCount[i])))-.691;if(blockLufs>Math.max(absolute,preliminary-10)){gated+=blockEnergy[i];gn+=blockCount[i];}}double measured=loudness.integrated();gain=Math.pow(10,(master.optDouble("target_lufs",-16)-measured)/20);m.notices.add("Android LOUDNORM uses K-weighted gated integrated loudness and a sample-peak ceiling. Oversampled true-peak parity with desktop FFmpeg is not certified.");}if(!mode.equals("OFF")&&peak*gain>ceiling)gain=ceiling/Math.max(peak,1e-9);File wav=new File(job,"preview-export.wav");try(DataInputStream in=new DataInputStream(new BufferedInputStream(new FileInputStream(floatFile),131072));BufferedOutputStream out=new BufferedOutputStream(new FileOutputStream(wav),131072)){wavHeader(out,frames);for(long i=0;i<frames*2;i++){if(i%8192==0)check(stop);write16(out,in.readFloat()*gain);}}voice.delete();if(music!=null)music.delete();floatFile.delete();progress.update("Audio ready",1);return wav;}
 public static File encodeAAC(File wav,File target,AtomicBoolean stop)throws Exception{MediaCodec codec=MediaCodec.createEncoderByType("audio/mp4a-latm");MediaMuxer muxer=null;boolean started=false;try{MediaFormat f=MediaFormat.createAudioFormat("audio/mp4a-latm",RATE,2);f.setInteger(MediaFormat.KEY_AAC_PROFILE,MediaCodecInfo.CodecProfileLevel.AACObjectLC);f.setInteger(MediaFormat.KEY_BIT_RATE,192000);f.setInteger(MediaFormat.KEY_MAX_INPUT_SIZE,16384);codec.configure(f,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);codec.start();muxer=new MediaMuxer(target.getPath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);boolean inputEnd=false,outputEnd=false;long bytes=0;int track=-1;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();try(InputStream in=new BufferedInputStream(new FileInputStream(wav))){long skipped=in.skip(44);if(skipped!=44)throw new IOException("Invalid mixed WAV.");while(!outputEnd){check(stop);if(!inputEnd){int ix=codec.dequeueInputBuffer(10000);if(ix>=0){ByteBuffer b=codec.getInputBuffer(ix);byte[]temp=new byte[Math.min(16384,b.capacity())];int n=in.read(temp);if(n<0){codec.queueInputBuffer(ix,0,0,bytes/4*1000000/RATE,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inputEnd=true;}else{b.put(temp,0,n);codec.queueInputBuffer(ix,0,n,bytes/4*1000000/RATE,0);bytes+=n;}}}int ox=codec.dequeueOutputBuffer(info,10000);if(ox==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){track=muxer.addTrack(codec.getOutputFormat());muxer.start();started=true;}else if(ox>=0){ByteBuffer b=codec.getOutputBuffer(ox);if((info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)!=0)info.size=0;if(info.size>0){if(!started)throw new IOException("AAC encoder returned samples before format.");b.position(info.offset);b.limit(info.offset+info.size);muxer.writeSampleData(track,b,info);}outputEnd=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(ox,false);}}}return target;}finally{try{codec.stop();}catch(Exception ignored){}codec.release();if(muxer!=null){if(started)try{muxer.stop();}catch(Exception ignored){}muxer.release();}}}
}
